using System;using System.Threading;using System.Threading.Tasks;using FluentAssertions;using Moq;using Mype.Application.BusinessMemberships.Interfaces;using Mype.Application.BusinessMemberships.Models;using Mype.Application.Categories.Interfaces;using Mype.Application.Common.Interfaces;using Mype.Application.FinancialMovements.Commands.UpdateSaleItem;using Mype.Application.FinancialMovements.Interfaces;using Mype.Application.Permissions.Interfaces;using Mype.Application.Products.Interfaces;using Mype.Domain.Businesses;using Mype.Domain.BusinessMemberships;using Mype.Domain.Categories;using Mype.Domain.FinancialMovements;using Mype.Domain.Permissions.Constants;using Mype.Domain.Products;
namespace Mype.Tests.Application.FinancialMovements.Commands.UpdateSaleItem
{public class UpdateSaleItemCommandHandlerTests{[Fact]public async Task Handle_Should_Update_Item_And_Set_Both_Versions(){var b=Guid.NewGuid();var u=Guid.NewGuid();var role=Guid.NewGuid();var m=FinancialMovement.CreateDraft(b,FinancialMovementType.Sale,new DateOnly(2026,10,10),null,"PEN",u,DateTimeOffset.UtcNow);var product=Product.Create(b,Guid.NewGuid(),"A","A",1m,1m,u,DateTimeOffset.UtcNow);var item=m.AddSaleItem(product,1m,1m,u,DateTimeOffset.UtcNow);var memberships=new Mock<IBusinessMembershipRepository>();memberships.Setup(x=>x.GetContextByBusinessAndUserAsync(b,u,It.IsAny<CancellationToken>())).ReturnsAsync(new BusinessContextProjection(b,"B","PEN",BusinessStatus.Active,Guid.NewGuid(),BusinessMembershipStatus.Active,role,"CUSTOM",true));var permissions=new Mock<IPermissionRepository>();permissions.Setup(x=>x.ListActiveCodesByRoleIdAsync(role,It.IsAny<CancellationToken>())).ReturnsAsync(new[]{SystemPermissions.MovementUpdate.Code});var movements=new Mock<IFinancialMovementRepository>();movements.Setup(x=>x.GetAggregateTrackedByIdAndBusinessAsync(m.Id,b,It.IsAny<CancellationToken>())).ReturnsAsync(m);var products=new Mock<IProductRepository>();products.Setup(x=>x.GetTrackedByIdAndBusinessAsync(product.Id,b,It.IsAny<CancellationToken>())).ReturnsAsync(product);var categories=new Mock<ICategoryRepository>();categories.Setup(x=>x.GetByIdAndBusinessAsync(product.CategoryId,b,It.IsAny<CancellationToken>())).ReturnsAsync(Category.CreateDefault(b,CategoryType.Sale,"Venta","VENTA",u,DateTimeOffset.UtcNow));var unit=new Mock<IUnitOfWork>();unit.Setup(x=>x.SaveChangesAsync(It.IsAny<CancellationToken>())).ReturnsAsync(2);var clock=new Mock<IClock>();clock.SetupGet(x=>x.UtcNow).Returns(DateTimeOffset.UtcNow);var handler=new UpdateSaleItemCommandHandler(memberships.Object,permissions.Object,movements.Object,products.Object,categories.Object,unit.Object,clock.Object);var result=await handler.Handle(new(){BusinessId=b,MovementId=m.Id,ItemId=item.Id,CurrentUserId=u,ProductId=product.Id,Quantity=3m,UnitAmount=4m,MovementVersion=9,ItemVersion=8},CancellationToken.None);result.IsSuccess.Should().BeTrue();result.Value.MovementTotal.Should().Be(12m);movements.Verify(x=>x.SetOriginalVersions(m,9,item,8),Times.Once);}}}
